1	package custody
2	
3	import (
4		"encoding/json"
5		"fmt"
6		"os"
7		"path/filepath"
8		"sort"
9		"strings"
10		"sync"
11		"time"
12	)
13	
14	// Store 是一份本地样品数据的入口。零值不可用，请通过 Open 创建或重新打开。
15	//
16	// 同一时刻所有读写操作都由一把互斥锁串行化，因此并发操作同一样品时，
17	// 既不会超量分装，也不会出现两条待确认交接。每次成功的写操作都会
18	// 原子落盘（临时文件 + rename），关闭后重新打开同一文件即可恢复
19	// 全部样品、保管历史以及交接编号的重复提交判断。
20	type Store struct {
21		path string
22		mu   sync.Mutex
23		data *ledger
24	
25		// now 可在同包测试中替换，便于确定性地控制事件时间。
26		now func() time.Time
27	}
28	
29	// Open 打开 path 指向的本地样品数据：文件不存在时创建一份新数据，
30	// 已存在时原样重新打开，历史记录与交接编号判断继续有效。
31	func Open(path string) (*Store, error) {
32		if strings.TrimSpace(path) == "" {
33			return nil, fmt.Errorf("%w: 数据文件路径不能为空", ErrInvalid)
34		}
35	
36		s := &Store{path: path, now: time.Now}
37	
38		raw, err := os.ReadFile(path)
39		switch {
40		case err == nil:
41			var l ledger
42			if err := json.Unmarshal(raw, &l); err != nil {
43				return nil, fmt.Errorf("读取本地样品数据 %s 失败: %w", path, err)
44			}
45			if l.Version != 1 {
46				return nil, fmt.Errorf("本地样品数据 %s 的版本 %d 不受支持", path, l.Version)
47			}
48			if l.Samples == nil {
49				l.Samples = make(map[string]*sampleRecord)
50			}
51			if l.Transfers == nil {
52				l.Transfers = make(map[string]*transferRecord)
53			}
54			if err := validateRestored(&l); err != nil {
55				return nil, err
56			}
57			s.data = &l
58		case os.IsNotExist(err):
59			s.data = newLedger()
60			if err := s.persist(s.data); err != nil {
61				return nil, err
62			}
63		default:
64			return nil, fmt.Errorf("打开本地样品数据 %s 失败: %w", path, err)
65		}
66		return s, nil
67	}
68	
69	// validateRestored 校验从文件恢复的数据中待确认交接关联是否一致。
70	// 样品的非空 pendingId 必须指向一条实际存在、尚未确认、且属于该样品的
71	// 交接；每条尚未确认的交接也必须对应一份实际存在、且 pendingId 正好指向
72	// 它的样品。已确认交接属于保留的历史，不要求样品继续指向它，也不核对
73	// 其与样品当前持有人、地点或剩余量的差异。集合中占用编号却为 null 的
74	// 条目视为损坏，不能当作记录不存在。任一问题都使整个文件无法恢复，
75	// 绝不只加载其中一部分，也不改动原文件。
76	func validateRestored(l *ledger) error {
77		sampleIDs := make([]string, 0, len(l.Samples))
78		for id := range l.Samples {
79			sampleIDs = append(sampleIDs, id)
80		}
81		sort.Strings(sampleIDs)
82		for _, id := range sampleIDs {
83			rec := l.Samples[id]
84			if rec == nil {
85				return fmt.Errorf("%w: 样品编号 %q 已被占用但记录为 null，无法恢复", ErrInvalid, id)
86			}
87			if rec.PendingID == "" {
88				continue
89			}
90			tr, ok := l.Transfers[rec.PendingID]
91			switch {
92			case !ok:
93				return fmt.Errorf("%w: 样品 %q 记着待确认交接 %q，但该交接不存在，无法恢复",
94					ErrInvalid, id, rec.PendingID)
95			case tr == nil:
96				return fmt.Errorf("%w: 样品 %q 记着待确认交接 %q，但该交接记录为 null，无法恢复",
97					ErrInvalid, id, rec.PendingID)
98			case tr.Confirmed:
99				return fmt.Errorf("%w: 样品 %q 记着的交接 %q 已确认，不能仍是待确认，无法恢复",
100					ErrInvalid, id, rec.PendingID)
101			case tr.SampleID != id:
102				return fmt.Errorf("%w: 样品 %q 记着的待确认交接 %q 属于样品 %q，无法恢复",
103					ErrInvalid, id, rec.PendingID, tr.SampleID)
104			}
105		}
106	
107		transferIDs := make([]string, 0, len(l.Transfers))
108		for id := range l.Transfers {
109			transferIDs = append(transferIDs, id)
110		}
111		sort.Strings(transferIDs)
112		for _, id := range transferIDs {
113			rec := l.Transfers[id]
114			if rec == nil {
115				return fmt.Errorf("%w: 交接编号 %q 已被占用但记录为 null，无法恢复", ErrInvalid, id)
116			}
117			if rec.Confirmed {
118				continue
119			}
120			sample, ok := l.Samples[rec.SampleID]
121			switch {
122			case !ok:
123				return fmt.Errorf("%w: 待确认交接 %q 对应的样品 %q 不存在，无法恢复",
124					ErrInvalid, id, rec.SampleID)
125			case sample == nil:
126				return fmt.Errorf("%w: 待确认交接 %q 对应的样品 %q 记录为 null，无法恢复",
127					ErrInvalid, id, rec.SampleID)
128			case sample.PendingID != id:
129				return fmt.Errorf("%w: 待确认交接 %q 的样品 %q 并未记着该交接编号，无法恢复",
130					ErrInvalid, id, rec.SampleID)
131			}
132		}
133		return nil
134	}
135	
136	// persist 把整份状态原子写入文件：先写同目录临时文件，再 rename 覆盖，
137	// 避免进程中断留下半截数据。
138	func (s *Store) persist(l *ledger) error {
139		raw, err := json.MarshalIndent(l, "", "  ")
140		if err != nil {
141			return fmt.Errorf("编码本地样品数据失败: %w", err)
142		}
143	
144		dir := filepath.Dir(s.path)
145		tmp, err := os.CreateTemp(dir, ".custody-*.tmp")
146		if err != nil {
147			return fmt.Errorf("创建临时数据文件失败: %w", err)
148		}
149		tmpName := tmp.Name()
150		defer os.Remove(tmpName)
151	
152		if _, err := tmp.Write(raw); err != nil {
153			tmp.Close()
154			return fmt.Errorf("写入临时数据文件失败: %w", err)
155		}
156		if err := tmp.Close(); err != nil {
157			return fmt.Errorf("关闭临时数据文件失败: %w", err)
158		}
159		if err := os.Rename(tmpName, s.path); err != nil {
160			return fmt.Errorf("替换本地样品数据文件失败: %w", err)
161		}
162		return nil
163	}
164	
165	// commit 在候选状态上落盘并替换内存状态。调用方必须保证 candidate
166	// 已通过全部校验；落盘失败时内存状态保持不变。
167	func (s *Store) commit(candidate *ledger) error {
168		if err := s.persist(candidate); err != nil {
169			return err
170		}
171		s.data = candidate
172		return nil
173	}
174	
175	// RegisterInput 是登记原样的入参。
176	type RegisterInput struct {
177		// ID 为样品编号，在这份数据内唯一，去空白后非空。
178		ID string
179		// Qty 为初始数量（毫升），大于零、最多三位小数的十进制字符串。
180		Qty string
181		// Holder 为初始持有人，去空白后非空。
182		Holder string
183		// Location 为初始地点，去空白后非空。
184		Location string
185	}
186	
187	// Register 登记一份原样。编号重复等冲突返回包装了 ErrConflict 的错误，
188	// 且不会写入任何记录。
189	func (s *Store) Register(in RegisterInput) (*Sample, error) {
190		s.mu.Lock()
191		defer s.mu.Unlock()
192	
193		id, err := trimRequired("样品编号", in.ID)
194		if err != nil {
195			return nil, err
196		}
197		holder, err := trimRequired("持有人", in.Holder)
198		if err != nil {
199			return nil, err
200		}
201		location, err := trimRequired("地点", in.Location)
202		if err != nil {
203			return nil, err
204		}
205		qty, err := parseQuantity(in.Qty)
206		if err != nil {
207			return nil, err
208		}
209		if _, exists := s.data.Samples[id]; exists {
210			return nil, fmt.Errorf("%w: 样品编号 %q 已存在", ErrConflict, id)
211		}
212	
213		candidate := s.data.deepCopy()
214		now := s.now().UTC()
215		candidate.Samples[id] = &sampleRecord{
216			ID:        id,
217			Initial:   qty,
218			Remaining: qty,
219			Holder:    holder,
220			Location:  location,
221			Children:  []string{},
222			History: []historyRecord{{
223				Kind:     "register",
224				Time:     now,
225				Holder:   holder,
226				Location: location,
227				Detail:   "登记原样",
228			}},
229		}
230		if err := s.commit(candidate); err != nil {
231			return nil, err
232		}
233		return buildSampleView(candidate.Samples[id], candidate), nil
234	}
235	
236	// SplitPart 是一次分装中的一个子样。
237	type SplitPart struct {
238		// ID 为子样编号，在这份数据内唯一，去空白后非空。
239		ID string
240		// Qty 为该子样数量（毫升），大于零、最多三位小数。
241		Qty string
242	}
243	
244	// SplitInput 是一次分装的入参；一次分装可以同时创建多个子样。
245	type SplitInput struct {
246		// ParentID 为来源样品编号。
247		ParentID string
248		// Parts 为本次要创建的全部子样，至少一个。
249		Parts []SplitPart
250	}
251	
252	// Split 执行一次原子分装。任一子样编号重复、数量不合法或子样总量超过
253	// 来源样品剩余量时，整次分装都不生效。成功后来源样品按整数刻度精确
254	// 扣减，子样继承当时的持有人和地点，并可继续分装。
255	//
256	// 返回来源样品的最新视图；子样可通过 GetSample 分别查询。
257	func (s *Store) Split(in SplitInput) (*Sample, error) {
258		s.mu.Lock()
259		defer s.mu.Unlock()
260	
261		parentID, err := trimRequired("来源样品编号", in.ParentID)
262		if err != nil {
263			return nil, err
264		}
265		if len(in.Parts) == 0 {
266			return nil, fmt.Errorf("%w: 一次分装至少要创建一个子样", ErrInvalid)
267		}
268	
269		parent, ok := s.data.Samples[parentID]
270		if !ok {
271			return nil, fmt.Errorf("%w: 来源样品 %q 不存在", ErrNotFound, parentID)
272		}
273	
274		// 先在局部完成全部校验，任何一项不通过都直接返回，不动状态。
275		type parsedPart struct {
276			id  string
277			qty int64
278		}
279		parsed := make([]parsedPart, 0, len(in.Parts))
280		seen := make(map[string]struct{}, len(in.Parts))
281		var total int64
282		for _, p := range in.Parts {
283			id, err := trimRequired("子样编号", p.ID)
284			if err != nil {
285				return nil, err
286			}
287			if _, dup := seen[id]; dup {
288				return nil, fmt.Errorf("%w: 本次分装中子样编号 %q 重复", ErrInvalid, id)
289			}
290			if _, exists := s.data.Samples[id]; exists {
291				return nil, fmt.Errorf("%w: 子样编号 %q 已存在", ErrConflict, id)
292			}
293			if id == parentID {
294				return nil, fmt.Errorf("%w: 子样编号 %q 不能与来源样品相同", ErrInvalid, id)
295			}
296			qty, err := parseQuantity(p.Qty)
297			if err != nil {
298				return nil, err
299			}
300			seen[id] = struct{}{}
301			parsed = append(parsed, parsedPart{id: id, qty: qty})
302			total += qty
303			if total < 0 {
304				return nil, fmt.Errorf("%w: 子样总量超出可表示范围", ErrInvalid)
305			}
306		}
307	
308		if parent.Destroyed != nil {
309			return nil, fmt.Errorf("%w: 样品 %q 已销毁，不能再分装", ErrConflict, parentID)
310		}
311		if parent.PendingID != "" {
312			return nil, fmt.Errorf("%w: 样品 %q 存在待确认交接 %s，不能分装",
313				ErrConflict, parentID, parent.PendingID)
314		}
315		if parent.Remaining == 0 {
316			return nil, fmt.Errorf("%w: 样品 %q 剩余量为零，不能再分装", ErrConflict, parentID)
317		}
318		if total > parent.Remaining {
319			return nil, fmt.Errorf("%w: 子样总量 %s 毫升超过样品 %q 的剩余量 %s 毫升",
320				ErrConflict, formatUnits(total), parentID, formatUnits(parent.Remaining))
321		}
322	
323		candidate := s.data.deepCopy()
324		cpParent := candidate.Samples[parentID]
325		now := s.now().UTC()
326	
327		childIDs := make([]string, 0, len(parsed))
328		for _, p := range parsed {
329			childIDs = append(childIDs, p.id)
330			candidate.Samples[p.id] = &sampleRecord{
331				ID:        p.id,
332				ParentID:  parentID,
333				Initial:   p.qty,
334				Remaining: p.qty,
335				Holder:    cpParent.Holder,
336				Location:  cpParent.Location,
337				Children:  []string{},
338				History: []historyRecord{{
339					Kind:     "split",
340					Time:     now,
341					Holder:   cpParent.Holder,
342					Location: cpParent.Location,
343					Detail:   fmt.Sprintf("由样品 %s 分装", parentID),
344				}},
345			}
346		}
347		cpParent.Remaining -= total
348		cpParent.Children = append(cpParent.Children, childIDs...)
349		cpParent.History = append(cpParent.History, historyRecord{
350			Kind:     "split",
351			Time:     now,
352			Holder:   cpParent.Holder,
353			Location: cpParent.Location,
354			Detail:   fmt.Sprintf("分装创建子样 %s", strings.Join(childIDs, ", ")),
355		})
356	
357		if err := s.commit(candidate); err != nil {
358			return nil, err
359		}
360		return buildSampleView(cpParent, candidate), nil
361	}
362	
363	// HandoverInput 是发起交接（交出）的入参。
364	type HandoverInput struct {
365		// TransferID 为本次交接编号，在本地数据中唯一，去空白后非空。
366		TransferID string
367		// SampleID 为要交出的样品编号。
368		SampleID string
369		// FromHolder 为交出人，必须与样品当前持有人完全一致（比较前对入参去空白）。
370		FromHolder string
371		// FromLocation 为交出地点，必须与样品当前地点完全一致。
372		FromLocation string
373		// ToHolder 为指定接收人，不能与交出人相同。
374		ToHolder string
375		// ToLocation 为目的地点。
376		ToLocation string
377		// HandedOverAt 为交出时间。
378		HandedOverAt time.Time
379	}
380	
381	// Handover 发起一次交接：转移该样品的全部剩余量，交接进入待确认状态，
382	// 原持有人和地点保持不变，直到指定接收人在目的地点确认。
383	//
384	// 交接编号已存在时：内容（样品、人员、地点、时间）完全一致则原样返回
385	// 既有交接（无论是否已确认）；任一内容不同则拒绝。
386	func (s *Store) Handover(in HandoverInput) (*TransferView, error) {
387		s.mu.Lock()
388		defer s.mu.Unlock()
389	
390		transferID, err := trimRequired("交接编号", in.TransferID)
391		if err != nil {
392			return nil, err
393		}
394		sampleID, err := trimRequired("样品编号", in.SampleID)
395		if err != nil {
396			return nil, err
397		}
398		fromHolder, err := trimRequired("交出人", in.FromHolder)
399		if err != nil {
400			return nil, err
401		}
402		fromLocation, err := trimRequired("交出地点", in.FromLocation)
403		if err != nil {
404			return nil, err
405		}
406		toHolder, err := trimRequired("接收人", in.ToHolder)
407		if err != nil {
408			return nil, err
409		}
410		toLocation, err := trimRequired("目的地点", in.ToLocation)
411		if err != nil {
412			return nil, err
413		}
414		if in.HandedOverAt.IsZero() {
415			return nil, fmt.Errorf("%w: 交出时间不能为空", ErrInvalid)
416		}
417		handedAt := in.HandedOverAt.UTC()
418	
419		if existing, ok := s.data.Transfers[transferID]; ok {
420			if !sameHandoverRequest(existing, sampleID, fromHolder, fromLocation, toHolder, toLocation, handedAt) {
421				return nil, fmt.Errorf("%w: 交接编号 %q 已被内容不同的交接使用", ErrConflict, transferID)
422			}
423			// 完全相同的重复提交：返回原交接，不增加任何记录。
424			return buildTransferView(existing), nil
425		}
426	
427		sample, ok := s.data.Samples[sampleID]
428		if !ok {
429			return nil, fmt.Errorf("%w: 样品 %q 不存在", ErrNotFound, sampleID)
430		}
431		if sample.Destroyed != nil {
432			return nil, fmt.Errorf("%w: 样品 %q 已销毁，不能发起新的交接", ErrConflict, sampleID)
433		}
434		if sample.Remaining == 0 {
435			return nil, fmt.Errorf("%w: 样品 %q 剩余量为零，不能发起交接", ErrConflict, sampleID)
436		}
437		if sample.PendingID != "" {
438			return nil, fmt.Errorf("%w: 样品 %q 已存在待确认交接 %s",
439				ErrConflict, sampleID, sample.PendingID)
440		}
441		if sample.Holder != fromHolder {
442			return nil, fmt.Errorf("%w: 交出人 %q 与样品 %q 当前持有人 %q 不一致",
443				ErrInvalid, fromHolder, sampleID, sample.Holder)
444		}
445		if sample.Location != fromLocation {
446			return nil, fmt.Errorf("%w: 交出地点 %q 与样品 %q 当前地点 %q 不一致",
447				ErrInvalid, fromLocation, sampleID, sample.Location)
448		}
449		if toHolder == fromHolder {
450			return nil, fmt.Errorf("%w: 接收人不能与交出人 %q 相同", ErrInvalid, fromHolder)
451		}
452	
453		candidate := s.data.deepCopy()
454		rec := &transferRecord{
455			ID:           transferID,
456			SampleID:     sampleID,
457			FromHolder:   fromHolder,
458			FromLocation: fromLocation,
459			ToHolder:     toHolder,
460			ToLocation:   toLocation,
461			Qty:          sample.Remaining,
462			HandedOverAt: handedAt,
463		}
464		candidate.Transfers[transferID] = rec
465		cpSample := candidate.Samples[sampleID]
466		cpSample.PendingID = transferID
467		cpSample.History = append(cpSample.History, historyRecord{
468			Kind:     "transfer-out",
469			Time:     handedAt,
470			Holder:   fromHolder,
471			Location: fromLocation,
472			Detail:   fmt.Sprintf("发起交接 %s，待 %s 在 %s 接收", transferID, toHolder, toLocation),
473		})
474	
475		if err := s.commit(candidate); err != nil {
476			return nil, err
477		}
478		return buildTransferView(rec), nil
479	}
480	
481	// sameHandoverRequest 判断已存交接与本次请求的内容是否完全相同。
482	func sameHandoverRequest(t *transferRecord, sampleID, fromHolder, fromLocation, toHolder, toLocation string, handedAt time.Time) bool {
483		return t.SampleID == sampleID &&
484			t.FromHolder == fromHolder &&
485			t.FromLocation == fromLocation &&
486			t.ToHolder == toHolder &&
487			t.ToLocation == toLocation &&
488			t.HandedOverAt.Equal(handedAt)
489	}
490	
491	// ConfirmInput 是确认接收的入参。
492	type ConfirmInput struct {
493		// TransferID 为待确认的交接编号。
494		TransferID string
495		// Receiver 为实际接收人，必须是发起时指定的接收人。
496		Receiver string
497		// AtLocation 为接收地点，必须是发起时的目的地点。
498		AtLocation string
499		// ReceivedAt 为接收时间，不能早于交出时间。
500		ReceivedAt time.Time
501	}
502	
503	// Confirm 由指定接收人在目的地点确认接收。确认后样品的持有人和地点
504	// 才真正改变，待确认状态结束。
505	//
506	// 对已确认交接重复提交完全相同的接收信息（接收人、地点、时间）时，
507	// 返回原结果且不增加转手记录；信息不同则拒绝。
508	func (s *Store) Confirm(in ConfirmInput) (*TransferView, error) {
509		s.mu.Lock()
510		defer s.mu.Unlock()
511	
512		transferID, err := trimRequired("交接编号", in.TransferID)
513		if err != nil {
514			return nil, err
515		}
516		receiver, err := trimRequired("接收人", in.Receiver)
517		if err != nil {
518			return nil, err
519		}
520		atLocation, err := trimRequired("接收地点", in.AtLocation)
521		if err != nil {
522			return nil, err
523		}
524		if in.ReceivedAt.IsZero() {
525			return nil, fmt.Errorf("%w: 接收时间不能为空", ErrInvalid)
526		}
527		receivedAt := in.ReceivedAt.UTC()
528	
529		rec, ok := s.data.Transfers[transferID]
530		if !ok {
531			// 明确的不存在错误，绝不顺带创建交接。
532			return nil, fmt.Errorf("%w: 交接 %q 不存在", ErrNotFound, transferID)
533		}
534	
535		if rec.Confirmed {
536			same := rec.ConfirmedBy == receiver &&
537				rec.ToLocation == atLocation &&
538				rec.ReceivedAt != nil && rec.ReceivedAt.Equal(receivedAt)
539			if !same {
540				return nil, fmt.Errorf("%w: 交接 %q 已确认，接收信息与原确认不一致", ErrConflict, transferID)
541			}
542			return buildTransferView(rec), nil
543		}
544	
545		if receiver != rec.ToHolder {
546			return nil, fmt.Errorf("%w: 只有指定接收人 %q 能确认交接 %q，实际确认人为 %q",
547				ErrConflict, rec.ToHolder, transferID, receiver)
548		}
549		if atLocation != rec.ToLocation {
550			return nil, fmt.Errorf("%w: 必须在目的地点 %q 确认交接 %q，实际地点为 %q",
551				ErrConflict, rec.ToLocation, transferID, atLocation)
552		}
553		if receivedAt.Before(rec.HandedOverAt) {
554			return nil, fmt.Errorf("%w: 接收时间不能早于交出时间 %s",
555				ErrInvalid, rec.HandedOverAt.Format(time.RFC3339))
556		}
557	
558		candidate := s.data.deepCopy()
559		cp := candidate.Transfers[transferID]
560		cp.Confirmed = true
561		cp.ConfirmedBy = receiver
562		receivedAtCopy := receivedAt
563		cp.ReceivedAt = &receivedAtCopy
564	
565		sample := candidate.Samples[cp.SampleID]
566		sample.Holder = receiver
567		sample.Location = atLocation
568		sample.PendingID = ""
569		sample.History = append(sample.History, historyRecord{
570			Kind:     "transfer-in",
571			Time:     receivedAt,
572			Holder:   receiver,
573			Location: atLocation,
574			Detail:   fmt.Sprintf("交接 %s 确认接收（交出时间 %s）", transferID, cp.HandedOverAt.Format(time.RFC3339)),
575		})
576	
577		if err := s.commit(candidate); err != nil {
578			return nil, err
579		}
580		return buildTransferView(cp), nil
581	}
582	
583	// DestroyInput 是销毁样品全部剩余量的入参；销毁不接受部分销毁。
584	type DestroyInput struct {
585		// SampleID 为样品编号。
586		SampleID string
587		// Operator 为操作人，去空白后必须与样品当前持有人一致。
588		Operator string
589		// Location 为销毁所在地点，去空白后必须与样品当前地点一致。
590		Location string
591		// At 为销毁时间，不能为零，也不能早于该样品任何已有保管历史的时间。
592		At time.Time
593		// Reason 为销毁原因，去空白后非空。
594		Reason string
595	}
596	
597	// Destroy 销毁该编号样品当时的全部剩余量（不接受部分销毁）。成功后
598	// 剩余量变为 0.000，初始量、来源关系、子样列表与原有保管历史保留，
599	// 持有人和地点保留为销毁前的最后记录，并在保管历史末尾追加一次销毁
600	// 事件；返回该样品的最新查询结果。
601	//
602	// 已销毁样品重复提交完全相同的操作人、地点、时间和原因时，返回原销毁
603	// 结果且不再追加历史；文本按去首尾空白后的内容比较，时间按实际时刻
604	// 比较。任一项不同则返回 ErrConflict，不覆盖原记录。
605	func (s *Store) Destroy(in DestroyInput) (*Sample, error) {
606		s.mu.Lock()
607		defer s.mu.Unlock()
608	
609		sampleID, err := trimRequired("样品编号", in.SampleID)
610		if err != nil {
611			return nil, err
612		}
613		operator, err := trimRequired("操作人", in.Operator)
614		if err != nil {
615			return nil, err
616		}
617		location, err := trimRequired("所在地点", in.Location)
618		if err != nil {
619			return nil, err
620		}
621		reason, err := trimRequired("销毁原因", in.Reason)
622		if err != nil {
623			return nil, err
624		}
625		if in.At.IsZero() {
626			return nil, fmt.Errorf("%w: 销毁时间不能为空", ErrInvalid)
627		}
628		at := in.At.UTC()
629	
630		rec, ok := s.data.Samples[sampleID]
631		if !ok {
632			return nil, fmt.Errorf("%w: 样品 %q 不存在", ErrNotFound, sampleID)
633		}
634	
635		// 已销毁：只接受与首次销毁完全相同的重复提交，原样返回且不再追加历史。
636		if rec.Destroyed != nil {
637			if !sameDestruction(rec.Destroyed, operator, location, at, reason) {
638				return nil, fmt.Errorf("%w: 样品 %q 已销毁，本次销毁信息与原销毁记录不一致",
639					ErrConflict, sampleID)
640			}
641			return buildSampleView(rec, s.data), nil
642		}
643	
644		// 未销毁样品的状态冲突（持有人/地点不匹配按入参语义归入冲突类）。
645		if operator != rec.Holder {
646			return nil, fmt.Errorf("%w: 操作人 %q 与样品 %q 当前持有人 %q 不一致",
647				ErrConflict, operator, sampleID, rec.Holder)
648		}
649		if location != rec.Location {
650			return nil, fmt.Errorf("%w: 销毁地点 %q 与样品 %q 当前地点 %q 不一致",
651				ErrConflict, location, sampleID, rec.Location)
652		}
653		if rec.PendingID != "" {
654			return nil, fmt.Errorf("%w: 样品 %q 存在待确认交接 %s，不能销毁",
655				ErrConflict, sampleID, rec.PendingID)
656		}
657		if rec.Remaining == 0 {
658			return nil, fmt.Errorf("%w: 样品 %q 剩余量已为零且未销毁，不能再销毁",
659				ErrConflict, sampleID)
660		}
661		for _, h := range rec.History {
662			if at.Before(h.Time) {
663				return nil, fmt.Errorf("%w: 销毁时间不能早于样品 %q 已有保管历史的时间 %s",
664					ErrInvalid, sampleID, h.Time.Format(time.RFC3339))
665			}
666		}
667	
668		candidate := s.data.deepCopy()
669		cp := candidate.Samples[sampleID]
670		destroyedQty := cp.Remaining
671		cp.Remaining = 0
672		cp.Destroyed = &destructionRecord{
673			Operator: operator,
674			Location: location,
675			At:       at,
676			Reason:   reason,
677			Qty:      destroyedQty,
678		}
679		// 持有人和地点保留为销毁前的最后记录，仅在历史末尾追加销毁事件。
680		cp.History = append(cp.History, historyRecord{
681			Kind:     "destroy",
682			Time:     at,
683			Holder:   operator,
684			Location: location,
685			Detail:   fmt.Sprintf("销毁全部剩余量 %s 毫升，原因：%s", formatUnits(destroyedQty), reason),
686		})
687	
688		if err := s.commit(candidate); err != nil {
689			return nil, err
690		}
691		return buildSampleView(cp, candidate), nil
692	}
693	
694	// sameDestruction 判断本次销毁请求与已有销毁记录是否完全相同。
695	// 文本字段均已去首尾空白，时间按实际时刻（Equal）比较。
696	func sameDestruction(d *destructionRecord, operator, location string, at time.Time, reason string) bool {
697		return d.Operator == operator &&
698			d.Location == location &&
699			d.At.Equal(at) &&
700			d.Reason == reason
701	}
702	
703	// GetSample 按样品编号查询：返回来源关系、初始量/剩余量、当前持有人和
704	// 地点、直接子样、按发生顺序排列的保管历史，以及待确认交接详情。
705	// 样品不存在时返回包装了 ErrNotFound 的错误，不会创建任何记录。
706	func (s *Store) GetSample(id string) (*Sample, error) {
707		s.mu.Lock()
708		defer s.mu.Unlock()
709	
710		sampleID, err := trimRequired("样品编号", id)
711		if err != nil {
712			return nil, err
713		}
714		rec, ok := s.data.Samples[sampleID]
715		if !ok {
716			return nil, fmt.Errorf("%w: 样品 %q 不存在", ErrNotFound, sampleID)
717		}
718		return buildSampleView(rec, s.data), nil
719	}
720	
721	// GetTransfer 按交接编号查询交接详情（待确认或已确认）。
722	// 交接不存在时返回包装了 ErrNotFound 的错误，不会创建任何记录。
723	func (s *Store) GetTransfer(id string) (*TransferView, error) {
724		s.mu.Lock()
725		defer s.mu.Unlock()
726	
727		transferID, err := trimRequired("交接编号", id)
728		if err != nil {
729			return nil, err
730		}
731		rec, ok := s.data.Transfers[transferID]
732		if !ok {
733			return nil, fmt.Errorf("%w: 交接 %q 不存在", ErrNotFound, transferID)
734		}
735		return buildTransferView(rec), nil
736	}
737	
738	// buildSampleView 把内部样品记录转换为对外视图，数量统一格式化为三位小数。
739	func buildSampleView(r *sampleRecord, l *ledger) *Sample {
740		children := append([]string{}, r.Children...)
741		history := make([]History, 0, len(r.History))
742		for _, h := range r.History {
743			history = append(history, History{
744				Kind:     h.Kind,
745				Time:     h.Time,
746				Holder:   h.Holder,
747				Location: h.Location,
748				Detail:   h.Detail,
749			})
750		}
751		v := &Sample{
752			ID:         r.ID,
753			ParentID:   r.ParentID,
754			InitialQty: formatUnits(r.Initial),
755			Remaining:  formatUnits(r.Remaining),
756			Holder:     r.Holder,
757			Location:   r.Location,
758			Children:   children,
759			History:    history,
760		}
761		if r.PendingID != "" {
762			if t, ok := l.Transfers[r.PendingID]; ok {
763				v.PendingTransfer = buildTransferView(t)
764			}
765		}
766		if r.Destroyed != nil {
767			v.Destruction = &Destruction{
768				Operator: r.Destroyed.Operator,
769				Location: r.Destroyed.Location,
770				At:       r.Destroyed.At,
771				Reason:   r.Destroyed.Reason,
772				Qty:      formatUnits(r.Destroyed.Qty),
773			}
774		}
775		return v
776	}
777	
778	// buildTransferView 把内部交接记录转换为对外视图。
779	func buildTransferView(r *transferRecord) *TransferView {
780		v := &TransferView{
781			TransferID:   r.ID,
782			SampleID:     r.SampleID,
783			FromHolder:   r.FromHolder,
784			FromLocation: r.FromLocation,
785			ToHolder:     r.ToHolder,
786			ToLocation:   r.ToLocation,
787			Qty:          formatUnits(r.Qty),
788			HandedOverAt: r.HandedOverAt,
789			Confirmed:    r.Confirmed,
790			ConfirmedBy:  r.ConfirmedBy,
791		}
792		if r.ReceivedAt != nil {
793			rx := *r.ReceivedAt
794			v.ReceivedAt = &rx
795			v.ConfirmedAt = r.ToLocation
796		}
797		return v
798	}
799

